package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b string
	fmt.Fscan(in, &a, &b)

	c := []string{"2", "3", "5", "7"}

	for x := 10; x <= 50; x++ {
		if x%2 == 0 || x%3 == 0 || x%5 == 0 || x%7 == 0 || x%9 == 0 {
			continue
		} else {
			c = append(c, fmt.Sprintf("%d", x))
		}
	}

	d := -1
	for i, v := range c {
		if v == a {
			d = i
			break
		}
	}

	if d != -1 && d+1 < len(c) && b == c[d+1] {
		fmt.Print("YES")
	} else {
		fmt.Print("NO")
	}
}

